def max_sum(arr):
    n = len(arr)

    if n == 1:
        return arr[0]

    # To store maximum sum of increasing subsequence ending at each index
    max_increasing = [0] * n
    max_increasing[0] = arr[0]

    for i in range(1, n):
        max_increasing[i] = arr[i]
        for j in range(i):
            if arr[i] > arr[j]:
                max_increasing[i] = max(max_increasing[i], max_increasing[j] + arr[i])

    # To store maximum sum of decreasing subsequence ending at each index
    max_decreasing = [0] * n
    max_decreasing[n - 1] = arr[n - 1]

    for i in range(n - 1, 0, -1):
        max_decreasing[i - 1] = arr[i - 1]
        for j in range(i, n):
            if arr[i - 1] > arr[j]:
                max_decreasing[i - 1] = max(max_decreasing[i - 1], max_decreasing[j] + arr[i - 1])

    max_bitonic = 0
    for i in range(n):
        if i > 0 and i < n - 1:
            max_bitonic = max(max_bitonic, max_increasing[i] + max_decreasing[i] - arr[i])
        else:
            max_bitonic = max(max_bitonic, max_increasing[i], max_decreasing[i])

